update public.content_variants set body_id = $json${"type":"calculation","answer":"9","question":"Menggunakan Aturan 72, berapa tahun yang dibutuhkan untuk menggandakan uang dengan pengembalian tahunan 8%?","difficulty":"intermediate","parameters":{"hint":"Bagi 72 dengan persentase pengembalian tahunan."},"explanation":"Aturan 72: Tahun untuk menggandakan = 72 / tingkat bunga. 72 / 8 = 9 tahun."}$json$::jsonb where id = 'f3efd05f-3cf0-4b2e-a4a6-387c67ff6e88';
update public.content_variants set body_id = $json${"type":"calculation","answer":"-2%","question":"Rekening tabungan Anda memberikan bunga 3% per tahun. Inflasi adalah 5%. Berapa perkiraan pengembalian riil Anda?","difficulty":"advanced","parameters":{"hint":"Kurangi inflasi dari tingkat bunga nominal."},"explanation":"Pengembalian riil ≈ pengembalian nominal - tingkat inflasi = 3% - 5% = -2%. Daya beli Anda menurun."}$json$::jsonb where id = 'f648b848-fff9-446b-a550-7316471daf97';
